// @name Tap counter
// @background #1e1b4b
// @refresh 3600
// The smallest interactive UI: onClick changes a number, active: darkens the
// button under the finger, and frameos.remember keeps the count.
let count = null
const load = () => {
  if (count === null) count = frameos.recall('count') ?? 0
}
const set = (n) => { count = n; frameos.remember('count', n) }

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-indigo-950 text-white',
    label: 'text-indigo-300',
    minus: 'bg-rose-500 active:bg-rose-700',
    plus: 'bg-emerald-500 active:bg-emerald-700',
    reset: 'px-5 py-3 bg-white/10 text-slate-300 active:bg-white/30',
  },
  high: {
    page: 'bg-white text-black',
    label: 'text-black',
    minus: 'bg-black',
    plus: 'bg-black',
    reset: 'px-[18px] py-[10px] bg-white border-2 border-black text-black',
  },
}

const Sign = ({ d }) => (
  <svg className="w-14 h-14 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round">
    <path d={d} />
  </svg>
)

export function get(app) {
  load()
  const t = highContrast(app) ? THEMES.high : THEMES.color
  return (
    <div className={`flex flex-col items-center justify-center gap-6 ${t.page}`}>
      <span className={`text-lg uppercase font-semibold ${t.label}`}>Tap counter</span>
      <span className="text-9xl font-bold">{`${count}`}</span>
      <div className="flex items-center gap-6">
        <div className={`w-28 h-28 rounded-full flex items-center justify-center ${t.minus}`} onClick={() => set(count - 1)}>
          <Sign d="M5 12h14" />
        </div>
        <div className={`rounded-xl text-lg ${t.reset}`} onClick={() => set(0)}>Reset</div>
        <div className={`w-28 h-28 rounded-full flex items-center justify-center ${t.plus}`} onClick={() => set(count + 1)}>
          <Sign d="M12 5v14M5 12h14" />
        </div>
      </div>
    </div>
  )
}
